async function showOpeningLegacy(page=1){const ticket=state.ticket,data=await api('/stock/movements?'+urlQuery({type:'opening',page,pageSize:50}));if(!active(ticket))return;showView('旧版期初流水',`<p class="mw-hint">保留旧版本单行期初登记，历史不重写为新单据。</p>${table(['物资 / 编码','数量 / 金额','区域 / 仓库 / 批次','日期'],data.items.map(row=>`<tr><td>${h(row.snapshot?.name)}<small>${h(row.snapshot?.code)}</small></td><td>${fmt(row.qtyM)} ${h(row.snapshot?.unit)}<small>${amount(row.amountCents)}</small></td><td>${h(row.snapshot?.regionName||nameOf(state.regions,row.regionId))} · ${h(warehouseName(row.warehouse))}<small>${h(row.batch||'未填写')}</small></td><td>${h(row.date)}<small>${h(row.actorName)}</small></td></tr>`).join(''))}${historyPages(data,'opening-legacy','')}`);}
async function fileContent(file){if(!file||!file.size)throw Error('请选择非空附件。');if(file.size>5*1024*1024)throw Error('单个附件不能超过 5 MiB。');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('无法读取附件，请重新选择。'));reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.readAsDataURL(file);});}
