    if(!allowed||(kind!=='cancel'&&!cap('issueStock')))throw Error('领用单状态或当前权限已变化，请重新查询。');
    const label={issue:'确认发放',reject:'驳回领用申请',cancel:'取消领用申请'}[kind];
    openForm({mode:'issue-process',issue,kind},label,kind==='issue'?(issue.trackingMode==='unit'?unitCodesField():''):input('reason','操作原因','',{type:'textarea',full:true}),`${h(issue.no||'#'+issue.id)} · ${h(issue.snapshot?.name)} · ${fmt(issue.qtyM)} ${h(issue.snapshot?.unit)}<br>批次 ${h(issue.batch||'未填写')} · 有效期 ${h(issue.expiryDate||'未填写')} · 存放位置 ${h((issue.location??issue.snapshot?.location)||'未设置')}<br>${kind==='issue'?(issue.trackingMode==='unit'?'请扫描本次发放的每瓶／每件编号，编号个数须等于申请数量；系统会检查是否仍在库。':'')+'确认后按实时批次余额扣库，金额由系统分摊。发放结果与库存流水保留，不能直接编辑已发放记录。':'办理后保留申请与处理原因，不产生出库流水。'}`,label);return;
