  if(action==='new-catalog'){openForm({mode:'catalog'},'新建规范物资主档',input('code','唯一物资编码')+input('name','物资名称')+input('spec','规格')+input('unit','基本单位','',{max:30})+select('categoryId','物资分类',dictionaryOptions(state.categories))+select('trackingMode','库存管理方式',[['unit','逐件管理（一瓶／一件一码）'],['quantity','按数量管理（可小数）']],'unit'),'逐件管理在验收、期初、盘盈时自动生成独立编号，数量须为整数；请使用瓶／件等整件单位。同名不同规格、纯度或单位应使用不同编码；引用后不直接修改物资身份。');return;}
  if(action==='catalog-search'){const context=state.form,form=el('mw-form'),query=form.elements.catalogQuery.value,selected=form.elements.catalogId.value,previous=state.catalog.find(row=>String(row.id)===selected),data=await api('/catalog?'+urlQuery({q:query,pageSize:200}));if(state.form!==context)return;state.catalog=data.items;if(previous&&!data.items.some(row=>row.id===previous.id))state.catalog.unshift(previous);const selectElement=form.elements.catalogId;selectElement.innerHTML='<option value="">新物资，先填写信息</option>'+state.catalog.map(row=>`<option value="${row.id}"${String(row.id)===selected?' selected':''}>${h(row.code+' · '+row.name+' · '+row.spec)}</option>`).join('');notify('找到 '+data.total+' 项主档'+(data.total>200?'，请缩小搜索范围。':'。'));return;}
  if(action==='opening'||action==='adjustment'){openForm({mode:action},action==='opening'?'登记期初库存':'库存调整',materialFields({},true)+input('amount','本批含税总金额（元）','',{decimal:true,note:action==='adjustment'?'允许为 0（如零值赠品）；数量须大于 0，调整原因必填。':''})+(action==='opening'?input('zeroAmountReason','零金额原因','',{required:false}):select('direction','调整方向',[['increase','增加库存'],['decrease','减少库存']],'increase'))+batchFields()+input('date','记账日期',day(),{type:'date'})+(action==='adjustment'?reasonField()+input('unitCodes','减少逐件库存时填写实物编号（一行一个）','',{type:'textarea',full:true,required:false,max:128999,note:'按数量管理或增加库存时留空；逐件管理减少库存必须填写对应在库实物编号。'})+btn('unit-code-scan','扫码添加实物编号'):''),action==='opening'?'只用于新账开始。首次验收入库或管理员确认后，期初登记将永久关闭。':'调整数量须大于 0，金额允许为 0，必须说明原因并保留流水。减少库存时须选择正确批次，数量及金额余额不能为负。','确认记账');return;}
