  if(action==='export'||action==='export-request'||action==='export-original'){if(action==='export'&&!['requests','inventory','issues'].includes(state.page))return;const query=action==='export'?{type:state.page==='inventory'?'stock':state.page==='issues'?'issues':'requests',...listFilters(),version:'current'}:{type:'requests',requestId:state.request.id,version:action==='export-original'?'original':'current'};await download('/export.xlsx?'+urlQuery(query),'物资-'+day()+'.xlsx');return;}
